import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
    const [juryName, setJuryName] = useState('');
    const [candidate, setCandidate] = useState('');
    const [team, setTeam] = useState('');
    const [candidates, setCandidates] = useState([]);
    const [teams, setTeams] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        fetch('http://localhost:3001/api/initial-data')
            .then(res => res.json())
            .then(data => {
                setCandidates(data.candidates);
                setTeams(data.teams);
            })
            .catch(err => console.error("Failed to fetch initial data:", err));
    }, []);

    const handleSubmit = (e) => {
        e.preventDefault();
        // Store jury info and navigate to evaluation page
        sessionStorage.setItem('juryInfo', JSON.stringify({ juryName, candidate, team }));
        navigate('/evaluation');
    };

    return (
        <div className="home-container">
            <div className="login-box">
                <h2>Jury Login</h2>
                <form onSubmit={handleSubmit}>
                    <div className="input-group">
                        <label>Your Name</label>
                        <input 
                            type="text" 
                            value={juryName} 
                            onChange={(e) => setJuryName(e.target.value)} 
                            required 
                        />
                    </div>
                    <div className="input-group">
                        <label>Select Candidate</label>
                        <select value={candidate} onChange={(e) => setCandidate(e.target.value)} required>
                            <option value="">--Select a Candidate--</option>
                            {candidates.map(c => (
                                <option key={c.name} value={c.name}>{c.name} ({c.team})</option>
                            ))}
                        </select>
                    </div>
                    <div className="input-group">
                        <label>Select Team</label>
                        <select value={team} onChange={(e) => setTeam(e.target.value)} required>
                            <option value="">--Select a Team--</option>
                            {teams.map(t => (
                                <option key={t.name} value={t.name}>{t.name}</option>
                            ))}
                        </select>
                    </div>
                    <button type="submit" className="submit-btn">Start Evaluation</button>
                </form>
            </div>
        </div>
    );
};

export default Home;
